import { z } from 'zod';

const id = z.string().min(1).max(64);
const quantity = z.number().int().min(1).max(100_000);
/** Generated by the client per action, so a double tap or retry applies once. */
const idempotencyKey = z.string().min(8).max(100);

export const lookupQuerySchema = z.object({ code: z.string().trim().min(1).max(64) });

export const receiveScanSchema = z.object({ skuId: id, quantity, idempotencyKey });
export type ReceiveScanInput = z.infer<typeof receiveScanSchema>;

export const putAwaySchema = z.object({ skuId: id, toBinId: id, quantity, idempotencyKey });
export type PutAwayInput = z.infer<typeof putAwaySchema>;

export const MOVE_REASONS = ['damaged', 'held', 'release', 'relocate'] as const;
export const moveSchema = z.object({
  skuId: id,
  fromBinId: id,
  toBinId: id,
  quantity,
  reason: z.enum(MOVE_REASONS),
  idempotencyKey,
});
export type MoveInput = z.infer<typeof moveSchema>;

export const countSchema = z.object({
  binId: id,
  lines: z
    .array(z.object({ skuId: id, countedQty: z.number().int().min(0).max(100_000) }))
    .max(500),
});
export type CountInput = z.infer<typeof countSchema>;

export const reviewCountSchema = z.object({ note: z.string().trim().max(300).optional() });

export const createManifestSchema = z.object({
  darkStoreId: id,
  reference: z.string().trim().min(1).max(60),
  note: z.string().trim().max(500).optional(),
  expectedAt: z.coerce.date().optional(),
  lines: z
    .array(z.object({ skuId: id, expectedQty: quantity }))
    .min(1)
    .max(200),
});
export type CreateManifestBody = z.infer<typeof createManifestSchema>;

export const STOCK_SOURCES = ['sellable', 'damaged', 'held'] as const;
export const RETURN_STATUSES = ['requested', 'picking', 'ready', 'collected', 'cancelled'] as const;

/** A merchant asks for units back from one store. */
export const createReturnSchema = z.object({
  darkStoreId: id,
  note: z.string().trim().max(500).optional(),
  lines: z
    .array(z.object({ skuId: id, source: z.enum(STOCK_SOURCES), quantity }))
    .min(1)
    .max(200),
});
export type CreateReturnBody = z.infer<typeof createReturnSchema>;

/** Staff scan a product (optionally after the bin) for a return. */
export const returnPickSchema = z.object({
  skuId: id,
  binId: id.optional(),
  quantity: quantity.default(1),
  idempotencyKey,
});
export type ReturnPickBody = z.infer<typeof returnPickSchema>;

export const returnHandOverSchema = z.object({
  collectedBy: z.string().trim().min(2).max(120),
});

export const cancelReturnSchema = z.object({ reason: z.string().trim().max(300).optional() });

export const DAMAGE_CAUSES = [
  'arrived_damaged',
  'store_handling',
  'delivery',
  'customer',
  'expired',
] as const;

/** Staff move units to the damaged bin and say why; admin settles who pays. */
export const reportDamageSchema = z.object({
  skuId: id,
  fromBinId: id,
  quantity,
  cause: z.enum(DAMAGE_CAUSES),
  note: z.string().trim().max(300).optional(),
  riderBadge: z.string().trim().max(40).optional(),
  idempotencyKey,
});
export type ReportDamageBody = z.infer<typeof reportDamageSchema>;

export const settleDamageSchema = z.object({
  cause: z.enum(DAMAGE_CAUSES),
  chargeRider: z.boolean().default(false),
  note: z.string().trim().max(300).optional(),
});
export type SettleDamageBody = z.infer<typeof settleDamageSchema>;

export const LOCATION_KINDS = ['dark_store', 'hub'] as const;

/** Admin opens a dark store or a sorting facility (hub). */
export const createLocationSchema = z.object({
  kind: z.enum(LOCATION_KINDS),
  code: z
    .string()
    .trim()
    .toUpperCase()
    .regex(/^[A-Z0-9]{2,8}$/),
  nameEn: z.string().trim().min(2).max(80),
  nameAr: z.string().trim().min(2).max(80),
  addressEn: z.string().trim().min(5).max(300),
  addressAr: z.string().trim().min(5).max(300),
  governorateId: z.number().int().min(1).max(27),
  latitude: z.number().min(22).max(32),
  longitude: z.number().min(24).max(37),
  shelves: z.number().int().min(1).max(200),
});
export type CreateLocationBody = z.infer<typeof createLocationSchema>;

export const addShelvesSchema = z.object({ count: z.number().int().min(1).max(100) });

export const TRANSFER_STATUSES = [
  'draft',
  'approved',
  'picking',
  'in_transit',
  'received',
  'cancelled',
] as const;

const transferLines = z
  .array(z.object({ skuId: id, quantity }))
  .min(1)
  .max(500);

/** Admin moves stock between locations; store to store goes through the hub. */
export const createTransferSchema = z.object({
  fromId: id,
  toId: id,
  note: z.string().trim().max(300).optional(),
  lines: transferLines,
});
export type CreateTransferBody = z.infer<typeof createTransferSchema>;

/** Approving a refill draft, optionally with changed quantities (0 drops a line). */
export const approveTransferSchema = z.object({
  lines: z
    .array(z.object({ skuId: id, quantity: z.number().int().min(0).max(100_000) }))
    .max(500)
    .optional(),
});

export const transferScanSchema = z.object({
  skuId: id,
  binId: id.optional(),
  quantity: quantity.default(1),
  idempotencyKey,
});
export type TransferScanBody = z.infer<typeof transferScanSchema>;
